CREATE OR REPLACE FUNCTION public.get_event_blast_plans_admin() RETURNS TABLE(id text, name text, unique_reach integer, duration_minutes integer, price_usd numeric, bc_price bigint, enabled boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$ BEGIN IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.user_roles r WHERE r.user_id = auth.uid() AND r.role = 'admin') THEN RAISE EXCEPTION 'Administrator access is required'; END IF; RETURN QUERY SELECT p.id, p.name, p.unique_reach, p.duration_minutes, p.price_usd, p.bc_price, p.enabled FROM public.event_blast_plans p ORDER BY p.unique_reach, p.name; END; $$; REVOKE EXECUTE ON FUNCTION public.get_event_blast_plans_admin() FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.get_event_blast_plans_admin() TO authenticated;
